.zoidium-color-curves-row {
  grid-template-columns: minmax(0, 1fr) !important;
  padding-bottom: 4px !important;
  white-space: normal !important;
}

.zoidium-color-curves-row > div:first-child {
  padding-bottom: 3px;
}

.zoidium-color-curves-row > div:nth-child(2) {
  min-width: 0;
  padding: 0 5px 5px !important;
}

.zoidium-color-curves-control,
.zoidium-color-curves-editor,
.zoidium-color-curves-control * {
  box-sizing: border-box;
  font-family: inherit;
}

.zoidium-color-curves-control {
  width: 100%;
  min-width: 0;
  color: #aaa;
}

.zoidium-color-curves-editor {
  --zoidium-curve-channel: var(--zoidium-theme-link, #7e8fb9);
  width: 100%;
  min-width: 0;
  border: 1px solid #1b1b1b;
  background: #242424;
}

.zoidium-color-curves-editor[data-channel="red"] {
  --zoidium-curve-channel: #c46f6f;
}

.zoidium-color-curves-editor[data-channel="green"] {
  --zoidium-curve-channel: #6fa47a;
}

.zoidium-color-curves-editor[data-channel="blue"] {
  --zoidium-curve-channel: #718fc4;
}

.zoidium-color-curves-toolbar {
  display: grid;
  grid-template-columns: repeat(4, minmax(28px, 1fr)) auto;
  min-height: 29px;
  border-bottom: 1px solid #1b1b1b;
  background: #2a2a2a;
}

.zoidium-color-curves-channel,
.zoidium-color-curves-reset {
  min-width: 0;
  height: 28px;
  padding: 0 7px;
  overflow: hidden;
  color: #aaa;
  background: transparent;
  border: 1px solid transparent;
  border-right-color: #222;
  outline: 0;
  font-size: 12px;
  line-height: 26px;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.zoidium-color-curves-channel:hover,
.zoidium-color-curves-reset:hover {
  color: #d0d0d0;
  background: #303030;
}

.zoidium-color-curves-channel:focus-visible,
.zoidium-color-curves-reset:focus-visible {
  border-color: var(--zoidium-theme-focus, #384668);
}

.zoidium-color-curves-channel.is-active {
  color: #e0e0e0;
  background: #202020;
  border-bottom-color: var(--zoidium-curve-channel);
}

.zoidium-color-curves-reset {
  display: flex;
  align-items: center;
  gap: 4px;
  justify-content: center;
  width: auto;
  padding: 0 6px;
  border-right-color: transparent;
}

.zoidium-color-curves-reset svg {
  width: 13px;
  height: 13px;
  flex: 0 0 auto;
  fill: currentColor;
  pointer-events: none;
}

.zoidium-color-curves-reset span {
  overflow: hidden;
  text-overflow: ellipsis;
}

.zoidium-color-curves-graph {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  overflow: hidden;
  touch-action: none;
  cursor: crosshair;
  background-color: #202020;
  background-image:
    linear-gradient(to right, transparent calc(25% - 0.5px), #303030 25%, transparent calc(25% + 0.5px)),
    linear-gradient(to right, transparent calc(50% - 0.5px), #353535 50%, transparent calc(50% + 0.5px)),
    linear-gradient(to right, transparent calc(75% - 0.5px), #303030 75%, transparent calc(75% + 0.5px)),
    linear-gradient(to bottom, transparent calc(25% - 0.5px), #303030 25%, transparent calc(25% + 0.5px)),
    linear-gradient(to bottom, transparent calc(50% - 0.5px), #353535 50%, transparent calc(50% + 0.5px)),
    linear-gradient(to bottom, transparent calc(75% - 0.5px), #303030 75%, transparent calc(75% + 0.5px));
  outline: 0;
}

.zoidium-color-curves-graph:focus-visible {
  box-shadow: inset 0 0 0 2px var(--zoidium-theme-focus, #384668);
}

.zoidium-color-curves-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.zoidium-color-curves-diagonal,
.zoidium-color-curves-reference,
.zoidium-color-curves-active {
  fill: none;
  pointer-events: none;
  vector-effect: non-scaling-stroke;
}

.zoidium-color-curves-diagonal {
  stroke: #4a4a4a;
  stroke-width: 1px;
  stroke-dasharray: 3 3;
}

.zoidium-color-curves-reference {
  stroke: #747474;
  stroke-width: 1px;
  opacity: 0.65;
}

.zoidium-color-curves-active {
  stroke: var(--zoidium-curve-channel);
  stroke-width: 2px;
}

.zoidium-color-curves-point-hit {
  fill: transparent;
  cursor: grab;
}

.zoidium-color-curves-point {
  fill: #202020;
  stroke: var(--zoidium-curve-channel);
  stroke-width: 2px;
  pointer-events: none;
  vector-effect: non-scaling-stroke;
}

.zoidium-color-curves-point-wrap.is-selected .zoidium-color-curves-point {
  fill: var(--zoidium-curve-channel);
  stroke: #e2e2e2;
}

.zoidium-color-curves-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 24px;
  padding: 3px 6px;
  overflow: hidden;
  color: #858585;
  background: #242424;
  border-top: 1px solid #1b1b1b;
  font-size: 11px;
  line-height: 17px;
}

.zoidium-color-curves-status,
.zoidium-color-curves-hint {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.zoidium-color-curves-status {
  color: var(--zoidium-curve-channel);
}

.zoidium-color-curves-hint {
  color: #727272;
  text-align: right;
}

